try {
    mainModule = import.meta.url === pathToFileURL(fs.realpathSync(process.argv[1] ?? '')).href;
}
catch { }
if (mainModule)
    void main().catch(() => { process.stderr.write('observation-adapter-unavailable\n'); process.exitCode = 1; });

